mkdir -p /tmp/rn && cat > /tmp/rn/r.js <<'EOF'
const fs=require('fs'),path=require('path');
function walk(d,o=[]){for(const f of fs.readdirSync(d)){const p=path.join(d,f);fs.statSync(p).isDirectory()?walk(p,o):/\.(ts|html)$/.test(f)&&o.push(p);}return o;}
let n=0;
for(const f of walk('src')){
  const s=fs.readFileSync(f,'utf8');let out='',i=0;
  const re=/<app-(pill|fancy-pill|status-pill)(?=[\s\/>])/g;let m;
  while((m=re.exec(s))){
    let j=m.index+m[0].length,q=null;
    for(;j<s.length;j++){const c=s[j];if(q){if(c===q)q=null;}else if(c==='"'||c==="'")q=c;else if(c==='>')break;}
    const tag=s.slice(m.index,j);
    // replace attr names outside quotes
    let t='',k=0;q=null;let seg='';
    const flush=()=>{t+=seg.replace(/(^|[\s\[])disableTooltip(?=[\s\]=\/>]|$)/g,(a,b)=>{n++;return b+'hideHint';});seg='';};
    for(;k<tag.length;k++){const c=tag[k];if(q){t+=c;if(c===q)q=null;}else if(c==='"'||c==="'"){flush();t+=c;q=c;}else seg+=c;}
    flush();
    out+=s.slice(i,m.index)+t;i=j;re.lastIndex=j;
  }
  out+=s.slice(i);
  if(out!==s)fs.writeFileSync(f,out);
}
console.log(n);
